package net.swordie.ms.world.tms282.items;

import net.swordie.ms.client.character.Char;
import net.swordie.ms.client.character.items.Tms282Beauty;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Style pools of 282 beauty coupons that the client data defines
 * ({@code data/resources/tms282/beauty/beauty-coupon-rules.tsv}, generated by
 * research/tms2823/item-usability-20260928/cash-use/gen_beauty_rules.py):
 * <ul>
 *     <li>{@code dye}: every colour of the current hair (Tms282Beauty kind 3);</li>
 *     <li>{@code lens}: every eye colour of the current face (kind 4);</li>
 *     <li>{@code named}: the styles the item description names, one per 282 catalogue family, with a gender.</li>
 * </ul>
 * {@code choice} coupons (Item.wz info/choice) list the pool in LP023E and the player picks; {@code random} ones get a
 * random member. The current look is never offered. Coupons without a rule have no defined pool.
 */
public final class Tms282BeautyCoupons {
    public record Style(int id, int gender) {
    }

    /** kind: 0 hair, 1 face, 2 skin (Tms282Beauty categories). */
    public record Rule(int coupon, boolean choice, String rule, int kind, List<Style> styles) {
        /** Tms282Beauty kind to apply with: dye 3, lens 4, otherwise the category. */
        public int applyKind() {
            return switch (rule) {
                case "dye" -> 3;
                case "lens" -> 4;
                default -> kind;
            };
        }
    }

    private static volatile Tms282BeautyCoupons shared;
    private final Map<Integer, Rule> rules;

    Tms282BeautyCoupons(Map<Integer, Rule> rules) {
        this.rules = Map.copyOf(rules);
    }

    public static Path defaultFile() {
        return Path.of(System.getProperty("tms282.boxesDir", "data/resources/tms282"), "beauty", "beauty-coupon-rules.tsv");
    }

    public static Tms282BeautyCoupons get() {
        Tms282BeautyCoupons t = shared;
        if (t == null) {
            synchronized (Tms282BeautyCoupons.class) {
                if (shared == null) {
                    Path f = defaultFile();
                    Tms282BeautyCoupons base = Files.isRegularFile(f) ? load(f) : new Tms282BeautyCoupons(Map.of());
                    shared = Files.isRegularFile(webFile()) ? base.withWebChoices(webFile()) : base;
                }
                t = shared;
            }
        }
        return t;
    }

    public static Tms282BeautyCoupons load(Path file) {
        Map<Integer, Rule> map = new HashMap<>();
        try {
            for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {
                if (line.isBlank() || !Character.isDigit(line.charAt(0))) {
                    continue;
                }
                String[] c = line.split("\t", -1);
                int coupon = Integer.parseInt(c[0].trim());
                int kind = switch (c[3].trim()) {
                    case "hair" -> 0;
                    case "face" -> 1;
                    case "skin" -> 2;
                    default -> throw new IllegalArgumentException("Beauty rule kind " + c[3]);
                };
                List<Style> styles = new ArrayList<>();
                for (String s : c[4].split(",")) {
                    if (!s.isBlank()) {
                        String[] p = s.trim().split(":");
                        styles.add(new Style(Integer.parseInt(p[0]), p.length > 1 ? Integer.parseInt(p[1]) : 2));
                    }
                }
                String rule = c[2].trim();
                if (!rule.equals("dye") && !rule.equals("lens") && !rule.equals("named")) {
                    throw new IllegalArgumentException("Beauty rule " + rule);
                }
                map.put(coupon, new Rule(coupon, "choice".equals(c[1].trim()), rule, kind, List.copyOf(styles)));
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return new Tms282BeautyCoupons(map);
    }

    /**
     * {@code beauty/beauty-coupon-pools-web.tsv}: pools taken from the official TW probability pages
     * (research/tms2823/item-usability-20260928/beauty-web). Columns: couponId, couponName, styleId, styleName,
     * gender, weight_or_prob (percent; blank = no-odds), source_url, confidence.
     */
    public static Path webFile() {
        return Path.of(System.getProperty("tms282.boxesDir", "data/resources/tms282"), "beauty", "beauty-coupon-pools-web.tsv");
    }

    /** One web-pool row; {@code prob} is null for a no-odds (choice) row. */
    public record WebRow(int coupon, int styleId, int gender, Double prob, String confidence) {
        /** 0 hair, 1 face (Tms282Beauty categories), from the style id range. */
        public int kind() {
            int p = styleId / 10000;
            return p == 2 || p == 5 ? 1 : 0;
        }

        /** Only high/medium rows are used; low ones are research notes. */
        public boolean trusted() {
            return confidence.startsWith("high") || confidence.startsWith("medium");
        }
    }

    public static List<WebRow> readWeb(Path file) {
        List<WebRow> out = new ArrayList<>();
        try {
            for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {
                if (line.isBlank() || !Character.isDigit(line.charAt(0))) {
                    continue;
                }
                String[] c = line.split("\t", -1);
                String p = c[5].trim();
                out.add(new WebRow(Integer.parseInt(c[0].trim()), Integer.parseInt(c[2].trim()), Integer.parseInt(c[4].trim()),
                        p.isEmpty() ? null : Double.valueOf(p), c[7].trim()));
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return out;
    }

    /**
     * Random coupons whose official pool is complete: every row trusted and with a probability, and each gender group
     * sums to 100% (+-1, the pages round to 2 decimals). Coupons with an unmapped (ambiguous) style fail the sum.
     */
    public static Map<Integer, List<WebRow>> completeRandomWebPools(Path file) {
        Map<Integer, List<WebRow>> by = new HashMap<>();
        for (WebRow r : readWeb(file)) {
            by.computeIfAbsent(r.coupon(), k -> new ArrayList<>()).add(r);
        }
        Map<Integer, List<WebRow>> out = new HashMap<>();
        by.forEach((coupon, rows) -> {
            if (rows.stream().anyMatch(r -> r.prob() == null || !r.trusted())) {
                return;
            }
            Map<Integer, Double> sums = new HashMap<>();
            rows.forEach(r -> sums.merge(r.gender(), r.prob(), Double::sum));
            if (sums.values().stream().allMatch(s -> Math.abs(s - 100.0) <= 1.0)) {
                out.put(coupon, List.copyOf(rows));
            }
        });
        return out;
    }

    /** Adds trusted no-odds web pools as {@code choice}/{@code named} rules; data-defined rules are kept as they are. */
    public Tms282BeautyCoupons withWebChoices(Path file) {
        Map<Integer, List<WebRow>> by = new HashMap<>();
        for (WebRow r : readWeb(file)) {
            if (r.prob() == null && r.trusted() && r.confidence().contains("no-odds")) {
                by.computeIfAbsent(r.coupon(), k -> new ArrayList<>()).add(r);
            }
        }
        Map<Integer, Rule> merged = new HashMap<>(rules);
        by.forEach((coupon, rows) -> merged.computeIfAbsent(coupon, k -> new Rule(coupon, true, "named", rows.get(0).kind(),
                rows.stream().map(r -> new Style(r.styleId(), r.gender())).distinct().toList())));
        return new Tms282BeautyCoupons(merged);
    }

    public Optional<Rule> rule(int coupon) {
        return Optional.ofNullable(rules.get(coupon));
    }

    public int size() {
        return rules.size();
    }

    /** Styles {@code chr} may get from the coupon right now (catalogue-valid, gender-matching, not the current look). */
    public static List<Integer> pool(Char chr, Rule r) {
        int gender = chr.getAvatarData().getAvatarLook().getGender();
        return pool(r, Tms282Beauty.current(chr, r.kind()), gender);
    }

    /** As {@link #pool(Char, Rule)} for a given current look (offline checks). */
    public static List<Integer> pool(Rule r, int current, int gender) {
        List<Integer> out = new ArrayList<>();
        if (r.rule().equals("named")) {
            for (Style s : r.styles()) {
                if ((s.gender() == 2 || s.gender() == gender) && s.id() != current && inCatalogue(r.kind(), s.id())) {
                    out.add(s.id());
                }
            }
            return out;
        }
        int applyKind = r.applyKind();
        int n = Tms282Beauty.count(applyKind, current, "");
        for (int page = 0; page * Tms282Beauty.PAGE_SIZE < n; page++) {
            for (int id : Tms282Beauty.page(applyKind, current, "", page)) {
                if (id != current) {
                    out.add(id);
                }
            }
        }
        return out;
    }

    private static boolean inCatalogue(int kind, int id) {
        try {
            Tms282Beauty.name(kind, id);
            return true;
        } catch (RuntimeException e) {
            return false;
        }
    }
}
